using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Text;
using System.Windows.Forms;
using DevExpress.XtraEditors;
using System.Threading;
using System.Collections;

using Libs;
using Global;
using DCore;
using SimsObject;
using SimsService;

namespace ScheduleManager.TeacherWork
{
    public partial class frmTeachingTimeAdded_V2 : FormBase, IForm
    {
        #region Consts

        public const string PERMISSION_EDIT = "SIM_TeachingTimeAdded_Edit";
        public const string PERMISSION_VIEW = "SIM_TeachingTimeAdded_View";
        #endregion


        #region Variables       

        private DataTable dtbData;
        DataTable dtbTeacher = null;
        bool bolIsRefresh = false;

        private int? intYearID_Current = null;
        private int? intSemester_Curent = null;

        #endregion

        #region Propeties


        #endregion

        #region IForm Members

        private static frmTeachingTimeAdded_V2 _instance = null;

        public static frmTeachingTimeAdded_V2 Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmTeachingTimeAdded_V2();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        #region Support Functions

        public frmTeachingTimeAdded_V2()
        {
            InitializeComponent();
        }

        private void CheckPermission()
        {
            gvData.OptionsBehavior.Editable = UserSession.HasPermission(PERMISSION_EDIT);            
        }      

        public void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {                
                if (bolIsRefresh)
                {
                    uTeacher.RefrehData();
                    uYearSemester.RefrehData();                    
                }
                else
                {
                    uTeacher.InitData();
                    uYearSemester.InitData();
                    gvData.SummaryCollection = "RequestTotal,Total";
                }
            }
        }

        public bool IsValidData(bool isShowMsg = true)
        {
            if (uYearSemester.YearIDEditValue == null || uYearSemester.SemesterEditValue == null)
            {
                if (isShowMsg)
                    MessageManager.Warning("Bạn phải chọn niên kì!");

                uYearSemester.Focus();
                return false;
            }
            return true;
        }

        private void EnsureIsEditColumn()
        {
            if (dtbData == null)
                return;

            if (!dtbData.Columns.Contains("IsEdit"))
            {
                dtbData.Columns.Add("IsEdit", typeof(int));
                foreach (DataRow drw in dtbData.Rows)
                    drw["IsEdit"] = 0;
            }
        }

        public void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                SIM_TeachingTimeAdded obj = new SIM_TeachingTimeAdded();
                dtbData = obj.GetDataTable("SIM_TeachingTimeAdded_SearchForEdit_Request_PM",
                                "@ScienceID", uTeacher.ScienceEditValue,
                                "@SubjectGroupID", uTeacher.SubjectGroupEditValue,
                                "@TeacherID", uTeacher.TeacherIDEditValue,                                
                                "@YearID", uYearSemester.YearIDEditValue,
                                "@Semester", uYearSemester.SemesterEditValue,
                                "@TeacherWorkIDList", lookupTeacherWorkID.ListID_Seleted
                                );

                if (dtbData != null)
                {
                    EnsureIsEditColumn();

                    gcData.DataSource = dtbData;
                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, "SIM_TeachingTimeAdded_SearchForEdit_Request_PM", bolIsRefresh);                    

                    mnuItemPrint.Enabled = mnuItemExportToExcel.Enabled = true;
                    btnSave.Enabled = mnuItemSave.Enabled = false;

                    mnuItemSetIsEdit.Enabled = dtbData.Rows.Count > 0 && gvData.OptionsBehavior.Editable;

                    bolIsRefresh = false;

                    intYearID_Current = uYearSemester.YearIDEditValueInt32;
                    intSemester_Curent = uYearSemester.SemesterEditValueInt32;

                }
                else
                    ErrorManager.Error("Việc tải thông tin bị lỗi!");

            }
        }

        /// <summary>
        /// Save dữ liệu ở lưới
        /// </summary>
        private bool SaveData()
        {
            if (dtbData != null)
            {
                SIM_TeachingTimeAdded item = new SIM_TeachingTimeAdded();
                item.BeginTransaction();
                item.UpdatedUser = UserSession.Username;
                item.YearID = intYearID_Current;
                item.Semester = intSemester_Curent;

                foreach (DataRow drw in dtbData.Rows)
                {
                    if (Convert.ToBoolean(drw["IsEdit"]))
                    {
                        item.TeacherID = drw["TeacherID"].ToString();
                        item.TeacherWorkID = Convert.ToInt32(drw["TeacherWorkID"]);
                        item.ClassSubjectID = Libs.MyConvert.ToInt64(drw["ClassSubjectID"]);

                        if (drw["Quantity"].ToString().Trim() != "")
                            item.Quantity = Convert.ToDecimal(drw["Quantity"]);
                        else
                            item.Quantity = null;

                        if (drw["Ratio"].ToString() != "" && item.Quantity != null)
                            item.Total = Math.Round(item.Quantity.Value * Convert.ToDecimal(drw["Ratio"]), 2, MidpointRounding.AwayFromZero);
                        else
                            item.Total = null;

                        if (!item.AddOrEdit())
                        {
                            ErrorManager.Error("Việc cập nhật bị lỗi!");
                            return false;
                        }
                    }
                }

                foreach (DataRow drw in dtbData.Rows)
                    drw["IsEdit"] = 0;

                item.CommitTransaction();
                return true;
            }
            return true;
        }

        private bool LoadTeacherWork()
        { 
            SIM_TeacherWork obj = new SIM_TeacherWork();
            DataTable dtb = obj.GetDataTable("SIM_TeacherWork_SearchCbx");

            if (dtb == null)
                return false;

            lookupTeacherWorkID.InitData(dtb, "--Chọn--", "TeacherWorkID", "TeacherWorkName");

            return true;
        }

        #endregion

        #region Form Actions

        private void frmTeachingTimeAdded_V2_Load(object sender, EventArgs e)
        {
            LoadReferenceData();
            CheckPermission();
            SetToolTip();
            LoadTeacherWork();

            if (IsValidData(false))
                LoadData();

        }       

        private void btnSearch_Click(object sender, EventArgs e)
        {
            if (btnSave.Enabled)
            {
                if (MessageManager.Confirm("Dữ liệu thay đổi vẫn chưa được cập nhật!\r\nBạn vẫn muốn tiếp tục nạp lại mà không cần cập nhật?") != System.Windows.Forms.DialogResult.Yes)
                    return;
            }
            if (IsValidData())
                new Thread(LoadData).Start();
        }

        private void btnSave_Click(object sender, EventArgs e)
        {
            if (SaveData())
            {
                btnSave.Enabled = mnuItemSave.Enabled = false;
            }
        }        

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }


        #endregion

        private void gvData_SelectionChanged(object sender, DevExpress.Data.SelectionChangedEventArgs e)
        {
            mnuItemDelete.Enabled = gvData.SelectedRowsCount > 0 && UserSession.HasPermission(PERMISSION_EDIT);
        }

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            LoadTeacherWork();
            bolIsRefresh = true;
            LoadReferenceData();
            dtbTeacher = null;

            if (IsValidData(false))
                new Thread(LoadData).Start();
        }

        private void mnuItemPrint_Click(object sender, EventArgs e)
        {
        }

        private void frmTeachingTimeAdded_V2_FormClosing(object sender, FormClosingEventArgs e)
        {

        }

        private void gvData_ValidatingEditor(object sender, DevExpress.XtraEditors.Controls.BaseContainerValidateEditorEventArgs e)
        {
            string strFieldName = gvData.FocusedColumn.FieldName;
            if (strFieldName == "Quantity" || strFieldName == "RequestQuantity")
            {
                if (e.Value == null || e.Value.ToString().Trim() == "")
                    e.Value = DBNull.Value;
            }
        }

        private void gvData_ValidateRow(object sender, DevExpress.XtraGrid.Views.Base.ValidateRowEventArgs e)
        {
            DataRow drw = gvData.GetDataRow(e.RowHandle);
            if (drw != null)
            {
                if (drw["Quantity"].ToString() != "" && drw["Ratio"].ToString() != "")
                    drw["Total"] = Math.Round(Convert.ToDecimal(drw["Quantity"]) * Convert.ToDecimal(drw["Ratio"]), 2, MidpointRounding.AwayFromZero);
                else
                    drw["Total"] = DBNull.Value;

                drw["IsEdit"] = 1;
                btnSave.Enabled = mnuItemSave.Enabled = true;
            }

        }

        private void mnuItemDelete_Click(object sender, EventArgs e)
        {
            int[] rows = gvData.GetSelectedRows();
            for (int i = rows.Length - 1; i >= 0; i--)
            {
                DataRow drw = gvData.GetDataRow(rows[i]);
                if (drw != null)
                {
                    drw["IsEdit"] = 1;
                    drw["Quantity"] = DBNull.Value;
                    drw["Total"] = DBNull.Value;

                    btnSave.Enabled = mnuItemSave.Enabled = true;
                }
            }
        }


        private void frmTeachingTimeAdded_V2_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F1:
                    this.ShowToolTip();
                    break;
                case Keys.F4:
                    if (mnuItemDelete.Enabled)
                        mnuItemDelete_Click(sender, null);
                    break;
                case Keys.F5:                    
                    mnuItemRefresh_Click(sender, null);
                    break;
                case Keys.F6:
                    if (btnSave.Enabled)
                        btnSave_Click(sender, null);
                    break;
            }
        }

        private void mnuItemSetIsEdit_Click(object sender, EventArgs e)
        {
            foreach (int i in gvData.GetSelectedRows())
            {
                DataRow drw = gvData.GetDataRow(i);
                if (drw == null)
                    continue;

                if (drw["Quantity"].ToString() != "" && drw["Ratio"].ToString() != "")
                    drw["Total"] = Math.Round(Convert.ToDecimal(drw["Quantity"]) * Convert.ToDecimal(drw["Ratio"]), 2, MidpointRounding.AwayFromZero);
                else
                    drw["Total"] = DBNull.Value;

                drw["IsEdit"] = 1;
            }

            btnSave.Enabled = mnuItemSave.Enabled = true;

            MessageManager.Info("Đã xử lý lại hệ số cho những dòng đang chọn!\r\nNhưng dữ liệu vẫn chưa lưu cho tới khi bạn nhấn cập nhật!");
        }

        private void mnuItemExportToExcel_Data_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

    }
}

