public bool IsValidData(bool isShowMsg = true)
{
    if (uYearSemester.YearIDEditValue == null)
    {
        if (isShowMsg)
            MessageManager.Warning("Bạn phải chọn niên khóa!");

        uYearSemester.Focus();
        return false;
    }

    if (!chkIsFullYear.Checked && uYearSemester.SemesterEditValue == null)
    {
        if (isShowMsg)
            MessageManager.Warning("Bạn phải chọn học kỳ!");

        uYearSemester.Focus();
        return false;
    }
    return true;
}

private DataTable SearchData(SIM_TeachingTimeAdded obj, int semester)
{
    DataTable dtb = obj.GetDataTable("SIM_TeachingTimeAdded_SearchForEdit_Request_PM",
                    "@ScienceID", uTeacher.ScienceEditValue,
                    "@SubjectGroupID", uTeacher.SubjectGroupEditValue,
                    "@TeacherID", uTeacher.TeacherIDEditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", semester,
                    "@IsOtherActivity", chkIsOtherActivity.Checked ? 1 : 0
                    );

    if (dtb != null)
    {
        if (!dtb.Columns.Contains("Semester"))
            dtb.Columns.Add("Semester", typeof(int));

        foreach (DataRow drw in dtb.Rows)
            drw["Semester"] = semester;
    }

    return dtb;
}

private void BindGridData()
{
    EnsureIsEditColumn();

    gcData.DataSource = dtbData;
    SystemService.SYS_GridColumnService.InitGridColumn(gvData, "SIM_TeachingTimeAdded_SearchForEdit_Request_PM", bolIsRefresh);

    mnuItemPrint.Enabled = mnuItemExportToExcel.Enabled = true;
    btnSave.Enabled = mnuItemSave.Enabled = false;

    mnuItemSetIsEdit.Enabled = dtbData.Rows.Count > 0 && gvData.OptionsBehavior.Editable;

    bolIsRefresh = false;

    intYearID_Current = uYearSemester.YearIDEditValueInt32;
    if (chkIsFullYear.Checked)
        intSemester_Curent = null;
    else
        intSemester_Curent = uYearSemester.SemesterEditValueInt32;
}

