public void LoadData()
{
    if (InvokeRequired)
        Invoke(new MethodInvoker(LoadData));
    else
    {
        SIM_TeachingTimeAdded obj = new SIM_TeachingTimeAdded();
        dtbData = obj.GetDataTable("SIM_TeachingTimeAdded_SearchForEdit_Request_PM",
                        "@ScienceID", uTeacher.ScienceEditValue,
                        "@SubjectGroupID", uTeacher.SubjectGroupEditValue,
                        "@TeacherID", uTeacher.TeacherIDEditValue,
                        "@YearID", uYearSemester.YearIDEditValue,
                        "@Semester", uYearSemester.SemesterEditValue,
                        "@IsOtherActivity", chkIsOtherActivity.Checked ? 1 : 0
                        );

        if (dtbData != null)
        {
            EnsureIsEditColumn();

            gcData.DataSource = dtbData;
            SystemService.SYS_GridColumnService.InitGridColumn(gvData, "SIM_TeachingTimeAdded_SearchForEdit_Request_PM", bolIsRefresh);

            mnuItemPrint.Enabled = mnuItemExportToExcel.Enabled = true;
            btnSave.Enabled = mnuItemSave.Enabled = false;

            mnuItemSetIsEdit.Enabled = dtbData.Rows.Count > 0 && gvData.OptionsBehavior.Editable;

            bolIsRefresh = false;

            intYearID_Current = uYearSemester.YearIDEditValueInt32;
            intSemester_Curent = uYearSemester.SemesterEditValueInt32;

        }
        else
            ErrorManager.Error("Việc tải thông tin bị lỗi!");

    }
}

input.new_string:
public void LoadData()
{
    if (InvokeRequired)
        Invoke(new MethodInvoker(LoadData));
    else
    {
        SIM_TeachingTimeAdded obj = new SIM_TeachingTimeAdded();

        if (chkIsFullYear.Checked)
        {
            DataTable dtbSemester1 = SearchData(obj, 1);
            DataTable dtbSemester2 = SearchData(obj, 2);

            if (dtbSemester1 == null || dtbSemester2 == null)
            {
                ErrorManager.Error("Việc tải thông tin bị lỗi!");
                return;
            }

            dtbData = dtbSemester1.Copy();
            foreach (DataRow drw in dtbSemester2.Rows)
                dtbData.ImportRow(drw);
        }
        else
        {
            dtbData = SearchData(obj, uYearSemester.SemesterEditValueInt32);
        }

        if (dtbData != null)
            BindGridData();
        else
            ErrorManager.Error("Việc tải thông tin bị lỗi!");

    }
