/// <summary>
/// Save dữ liệu ở lưới
/// </summary>
private bool SaveData()
{
    if (dtbData != null)
    {
        SIM_TeachingTimeAdded item = new SIM_TeachingTimeAdded();
        item.BeginTransaction();
        item.UpdatedUser = UserSession.Username;
        item.YearID = intYearID_Current;

        foreach (DataRow drw in dtbData.Rows)
        {
            if (Convert.ToBoolean(drw["IsEdit"]))
            {
                if (dtbData.Columns.Contains("Semester") && drw["Semester"].ToString() != "")
                    item.Semester = Convert.ToInt32(drw["Semester"]);
                else
                    item.Semester = intSemester_Curent;

                item.TeacherID = drw["TeacherID"].ToString();
                item.TeacherWorkID = Convert.ToInt32(drw["TeacherWorkID"]);
                item.ClassSubjectID = Libs.MyConvert.ToInt64(drw["ClassSubjectID"]);

                if (drw["Quantity"].ToString().Trim() != "")
                    item.Quantity = Convert.ToDecimal(drw["Quantity"]);
                else
                    item.Quantity = null;

                if (drw["Ratio"].ToString() != "" && item.Quantity != null)
                    item.Total = Math.Round(item.Quantity.Value * Convert.ToDecimal(drw["Ratio"]), 2, MidpointRounding.AwayFromZero);
                else
                    item.Total = null;

                if (!item.AddOrEdit())
                {
                    ErrorManager.Error("Việc cập nhật bị lỗi!");
                    return false;
                }
            }
        }

        foreach (DataRow drw in dtbData.Rows)
            drw["IsEdit"] = 0;

        item.CommitTransaction();
        return true;
    }
    return true;
}

