        else
            drw["RequestTotal"] = DBNull.Value;

        if (drw["Quantity"].ToString() != "" && drw["Ratio"].ToString() != "")
            drw["Total"] = Math.Round(Convert.ToDecimal(drw["Quantity"]) * Convert.ToDecimal(drw["Ratio"]), 2, MidpointRounding.AwayFromZero);
