private object GetTeacherWorkIDFilter()
{
    object objValue = lookupTeacherWorkID.EditValue;
    if (objValue == null || objValue == DBNull.Value)
        return null;

    string strValue = objValue.ToString().Trim();
    if (strValue == "" || strValue == "--Chọn--" || strValue == "0")
        return null;

    return objValue;
}

private void AddEmptyTeacherWorkRow(DataTable dtb)
{
    DataRow drwEmpty = dtb.NewRow();
    drwEmpty["TeacherWorkID"] = DBNull.Value;
    drwEmpty["TeacherWorkName"] = "--Chọn--";

    if (dtb.Columns.Contains("TeacherWorkCode"))
        drwEmpty["TeacherWorkCode"] = "";
    if (dtb.Columns.Contains("TeacherWorkShortName"))
        drwEmpty["TeacherWorkShortName"] = "";
    if (dtb.Columns.Contains("TeacherWorkGroupName"))
        drwEmpty["TeacherWorkGroupName"] = "";

    dtb.Rows.InsertAt(drwEmpty, 0);
}

private bool LoadTeacherWork()
{
    SIM_TeacherWork obj = new SIM_TeacherWork();
    object semester = null;
    if (!chkIsFullYear.Checked && uYearSemester.SemesterEditValue != null)
        semester = uYearSemester.SemesterEditValueInt32;

    object objTeacherWorkID = lookupTeacherWorkID.EditValue;

    DataTable dtb = obj.GetDataTable("SIM_TeacherWork_SearchCbx",
                        "@YearID", uYearSemester.YearIDEditValue,
                        "@Semester", semester
                        );

    if (dtb == null)
        return false;

    AddEmptyTeacherWorkRow(dtb);
    lookupTeacherWorkID.InitData(dtb, "", "TeacherWorkID", "TeacherWorkName");
    lookupTeacherWorkID.EditValue = objTeacherWorkID;

    if (GetTeacherWorkIDFilter() == null)
        lookupTeacherWorkID.EditValue = null;

    return true;
}

